import { hasRule } from "@mdit/helper";
import type { BlockRule, PluginWithOptions } from "@mdit/helper";
import type { StateBlock } from "markdown-it";

import type { MarkdownItAlertOptions } from "./options.js";

const hasTerminatingRule = (
  rules: readonly BlockRule[],
  state: StateBlock,
  line: number,
  endLine: number,
): boolean => {
  for (let i = 0; i < rules.length; i++) if (rules[i](state, line, endLine, true)) return true;

  return false;
};

const getAlertRule =
  // oxlint-disable-next-line max-lines-per-function
  (types: Set<string>, deep: boolean): BlockRule => {
    // The alert class only depends on the validated type, so it is only built once per type.
    const alertClasses = new Map<string, string>();

    // oxlint-disable-next-line max-lines-per-function
    return (state, startLine, endLine, silent) => {
      // Save the state before any modification, so it can always be restored,
      // including in silent mode.
      const oldLineMax = state.lineMax;
      const oldParentType = state.parentType;

      if (
        // if it's indented more than 3 spaces, it should be a code block
        state.sCount[startLine] - state.blkIndent >= 4 ||
        // check whether it's at first level
        (state.level !== 0 && !deep)
      )
        return false;

      let pos = state.bMarks[startLine] + state.tShift[startLine];
      let max = state.eMarks[startLine];

      // check the block quote marker
      if (state.src.charCodeAt(pos) !== 62 /* > */) return false;

      let currentPos = pos + 1;

      let initial = state.sCount[startLine] + 1;
      let adjustTab = false;

      // skip one optional space after '>'
      if (state.src.charCodeAt(currentPos) === 32 /* space */) {
        // ' >   [!tip] '
        //     ^ -- position start of line here:
        currentPos++;
        initial++;
      } else if (state.src.charCodeAt(currentPos) === 9 /* tab */) {
        if ((state.bsCount[startLine] + initial) % 4 === 3) {
          // '  >\t  [!tip] '
          //       ^ -- position start of line here (tab has width===1)
          currentPos++;
          initial++;
        } else {
          // ' >\t  [!tip] '
          //    ^ -- position start of line here + shift bsCount slightly
          //         to make extra space appear
          adjustTab = true;
        }
      }

      let offset = initial;

      while (currentPos < max) {
        const ch = state.src.charCodeAt(currentPos);

        if (ch === 9 /** \t */)
          offset += 4 - ((offset + state.bsCount[startLine] + (adjustTab ? 1 : 0)) % 4);
        else if (ch === 32 /** Space */) offset++;
        else break;

        currentPos++;
      }

      // skip blockquote
      if (offset - initial >= 4) return false;

      // the minimum length of an alert is 4 characters [!x]
      if (max - currentPos < 4) return false;

      // check opening marker '[!'
      if (
        state.src.charCodeAt(currentPos) !== 91 /* [ */ ||
        state.src.charCodeAt(currentPos + 1) !== 33 /* ! */
      )
        return false;

      currentPos += 2;

      const typeNameStart = currentPos;

      // find closing bracket ']'
      while (currentPos < max && state.src.charCodeAt(currentPos) !== 93 /* ] */) currentPos++;

      if (currentPos === max) return false;

      const typeName = state.src.slice(typeNameStart, currentPos);
      const type = typeName.toLowerCase();

      if (!types.has(type)) return false;

      // skip spaces after ']'
      currentPos = state.skipSpaces(currentPos + 1);

      // if there are non-space characters after ']', it's not a valid alert
      if (currentPos < max) return false;

      const oldBMarks: number[] = [];
      const oldBSCount: number[] = [];
      const oldSCount: number[] = [];
      const oldTShift: number[] = [];
      const blockquoteTerminatorRules = state.md.block.ruler.getRules("blockquote");
      const alertTerminatorRules = state.md.block.ruler.getRules("alert");

      state.parentType = "alert";

      // Search the end of the block
      //
      // Block ends with either:
      //  1. an empty line outside:
      //     ```
      //     > test
      //
      //     ```
      //  2. an empty line inside:
      //     ```
      //     >
      //     test
      //     ```
      //  3. another tag:
      //     ```
      //     > test
      //      - - -
      //     ```
      let currentLine = startLine;
      let lastLineEmpty = false;
      let hasBodyContent = false;
      let terminated = false;

      for (; currentLine < endLine; currentLine++) {
        // check if it's outdented, i.e. it's inside list item and indented
        // less than said list item:
        //
        // ```
        // 1. anything
        //    > current blockquote
        // 2. checking this line
        // ```
        const isOutdented = state.sCount[currentLine] < state.blkIndent;

        pos = state.bMarks[currentLine] + state.tShift[currentLine];
        max = state.eMarks[currentLine];

        // Case 1: line is not inside the blockquote, and this line is empty.
        if (pos >= max) break;

        if (state.src.charCodeAt(pos++) === 62 /* > */ && !isOutdented) {
          // This line is inside the blockquote.

          let spaceAfterMarker = false;
          // set offset past spaces and ">"
          initial = state.sCount[currentLine] + 1;
          adjustTab = false;

          // skip one optional space after '>'
          if (state.src.charCodeAt(pos) === 32 /* space */) {
            // ' >   test '
            //     ^ -- position start of line here:
            pos++;
            initial++;
            spaceAfterMarker = true;
          } else if (state.src.charCodeAt(pos) === 9 /* \t */) {
            spaceAfterMarker = true;

            if ((state.bsCount[currentLine] + initial) % 4 === 3) {
              // '  >\t  test '
              //       ^ -- position start of line here (tab has width===1)
              pos++;
              initial++;
            } else {
              // ' >\t  test '
              //    ^ -- position start of line here + shift bsCount slightly
              //         to make extra space appear
              adjustTab = true;
            }
          }

          offset = initial;

          if (!silent) {
            oldBMarks.push(state.bMarks[currentLine]);
            state.bMarks[currentLine] = pos;
          }

          while (pos < max) {
            const ch = state.src.charCodeAt(pos);

            if (ch === 9 /** \t */)
              offset += 4 - ((offset + state.bsCount[currentLine] + (adjustTab ? 1 : 0)) % 4);
            else if (ch === 32 /** Space */) offset++;
            else break;

            pos++;
          }

          lastLineEmpty = pos >= max;
          if (currentLine > startLine && !lastLineEmpty) hasBodyContent = true;

          if (!silent) {
            oldBSCount.push(state.bsCount[currentLine]);
            state.bsCount[currentLine] = state.sCount[currentLine] + 1 + (spaceAfterMarker ? 1 : 0);

            oldSCount.push(state.sCount[currentLine]);
            state.sCount[currentLine] = offset - initial;

            oldTShift.push(state.tShift[currentLine]);
            state.tShift[currentLine] = pos - state.bMarks[currentLine];
          }
          continue;
        }

        if (isOutdented) break;

        // Case 2: line is not inside the blockquote, and the last line was empty.
        if (lastLineEmpty) break;

        // Case 3: another tag found.
        let terminate = hasTerminatingRule(blockquoteTerminatorRules, state, currentLine, endLine);

        if (!terminate)
          terminate = hasTerminatingRule(alertTerminatorRules, state, currentLine, endLine);

        if (terminate) {
          // Quirk to enforce "hard termination mode" for paragraphs;
          // normally if you call `tokenize(state, startLine, nextLine)`,
          // paragraphs will look below nextLine for paragraph continuation,
          // but if blockquote is terminated by another tag, they shouldn't.
          // Only record the line here: `state.lineMax` must not be modified
          // until the alert is confirmed and the rule is not in silent mode.
          terminated = true;

          if (state.blkIndent !== 0 && !silent) {
            // state.blkIndent was non-zero, we now set it to zero,
            // so we need to re-calculate all offsets to appear as
            // if indent wasn't changed
            oldBMarks.push(state.bMarks[currentLine]);
            oldBSCount.push(state.bsCount[currentLine]);
            oldSCount.push(state.sCount[currentLine]);
            oldTShift.push(state.tShift[currentLine]);

            state.sCount[currentLine] -= state.blkIndent;
          }

          break;
        }

        hasBodyContent = true;

        if (!silent) {
          oldBMarks.push(state.bMarks[currentLine]);
          oldBSCount.push(state.bsCount[currentLine]);
          oldSCount.push(state.sCount[currentLine]);
          oldTShift.push(state.tShift[currentLine]);

          // A negative indentation means that this is a paragraph continuation
          // we only set it if it's not the first line of the body
          if (currentLine > startLine + 1) state.sCount[currentLine] = -1;
        }
      }

      const restoreState = (): void => {
        state.lineMax = oldLineMax;
        state.parentType = oldParentType;

        // Restore original tShift; this might not be necessary since the parser
        // has already been here, but just to make sure we can do that.
        for (let i = 0; i < oldTShift.length; i++) {
          state.bMarks[i + startLine] = oldBMarks[i];
          state.tShift[i + startLine] = oldTShift[i];
          state.sCount[i + startLine] = oldSCount[i];
          state.bsCount[i + startLine] = oldBSCount[i];
        }
      };

      // If we didn't find any alert body, so we don't have a valid alert
      if (startLine + 1 >= currentLine || !hasBodyContent) {
        // Always restore the state, including in silent mode.
        restoreState();

        return false;
      }

      // from now we know that it's going to be a valid alert,
      // so no point trying to find the end of it in silent mode
      if (silent) {
        // The rule must not have side effects in silent mode.
        restoreState();

        return true;
      }

      const oldIndent = state.blkIndent;

      state.blkIndent = 0;

      // Only enforce "hard termination mode" once the alert is confirmed
      if (terminated) state.lineMax = currentLine;

      const titleLines: [number, number] = [startLine, startLine + 1];
      const contentLines: [number, number] = [startLine + 1, 0];

      let alertClass = alertClasses.get(type);

      if (!alertClass) {
        alertClass = `markdown-alert markdown-alert-${type}`;
        alertClasses.set(type, alertClass);
      }

      const openToken = state.push("alert_open", "div", 1);

      openToken.markup = type;
      openToken.attrs = [["class", alertClass]];
      openToken.map = contentLines;

      const titleToken = state.push("alert_title", "", 0);

      titleToken.attrs = [["class", "markdown-alert-title"]];
      titleToken.markup = type;
      titleToken.content = typeName;
      titleToken.map = titleLines;

      state.md.block.tokenize(state, startLine + 1, currentLine);

      const closeToken = state.push("alert_close", "div", -1);

      closeToken.markup = type;
      contentLines[1] = state.line;

      state.blkIndent = oldIndent;
      restoreState();

      return true;
    };
  };

/**
 * Alert plugin, rendering `> [!tip]` style blockquotes as alerts
 *
 * 提示框插件，将 `> [!tip]` 形式的引用块渲染为提示框
 *
 * @param md - MarkdownIt instance / MarkdownIt 实例
 * @param options - Alert options / 提示框选项
 */
export const alert: PluginWithOptions<MarkdownItAlertOptions> = (
  md,
  {
    alertNames = ["tip", "warning", "caution", "important", "note"],
    deep = false,
    openRenderer,
    closeRenderer,
    titleRenderer,
  } = {},
) => {
  // Repeated installation is a full no-op: the first installation's parse options and
  // renderers always win.
  if (hasRule(md, "alert", "block")) return;

  const normalizedNames = new Set(alertNames.map((name) => name.toLowerCase()));

  md.block.ruler.before("blockquote", "alert", getAlertRule(normalizedNames, deep), {
    alt: ["paragraph", "reference", "blockquote", "list"],
  });

  if (openRenderer) md.renderer.rules.alert_open = openRenderer;

  if (closeRenderer) md.renderer.rules.alert_close = closeRenderer;

  // Title content is a validated alert name, so only its casing variants can occur.
  // The rendered inline HTML can therefore be reused for the same title content.
  const titleCache = new Map<string, string>();

  md.renderer.rules.alert_title =
    titleRenderer ??
    ((tokens, index): string => {
      const { content } = tokens[index];
      let title = titleCache.get(content);

      if (!title) {
        // capitalize the first letter and render the title as inline markdown,
        // which escapes HTML unless the `html` option is enabled
        title = md.renderInline(content[0].toUpperCase() + content.slice(1));
        titleCache.set(content, title);
      }

      return `<p class="markdown-alert-title">${title}</p>\n`;
    });
};
